'use strict';
const $=s=>document.querySelector(s),gan=[...'甲乙丙丁戊己庚辛壬癸'],zhi=[...'子丑寅卯辰巳午未申酉戌亥'],wx=['木','木','火','火','土','土','金','金','水','水'];
const profileStyle=document.createElement('link');profileStyle.rel='stylesheet';profileStyle.href='start-profile.css';document.head.append(profileStyle);
const now=new Date();$('#birthday').max=`${now.getFullYear()-18}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;
const quickFields=[['age','年龄','例如：35'],['height','身高（cm）','例如：165'],['weight','体重（kg）','例如：50'],['school','学校学历','例如：北京大学硕士'],['job','职业','例如：产品经理'],['industry','行业','例如：科技互联网'],['title','职级 / Title','例如：高级产品经理'],['income','税前年收入区间','例如：30—50万元'],['assets','本人净资产区间 / A几','例如：300—500万元 · A7']];
let profileDraft={};
const quick=document.createElement('details');quick.id='quick-profile';quick.innerHTML='<summary>＋ 补充我的九项亮点，一起做成海报</summary><p>可以现在填写，也可以先查日主。生成完整交友卡前需补齐；父母资料不采集，内容不会自动公开或入库。</p><div class="quick-grid">'+quickFields.map(([k,t,placeholder])=>`<label>${t}<input name="quick-${k}" placeholder="${placeholder}" maxlength="90" ${['age','height','weight'].includes(k)?`type="number" min="${k==='age'?18:k==='height'?100:25}" max="${k==='age'?100:k==='height'?240:250}"`:''}></label>`).join('')+'</div><p>自由职业、在读、无职级等情况可如实填写。</p>';
$('#birth-form').querySelector('.consent').before(quick);
function getDay(y,m,d){if(m<=2){y--;m+=12;}const a=Math.floor(y/100),b=2-a+Math.floor(a/4),jd=Math.floor(365.25*(y+4716))+Math.floor(30.6001*(m+1))+d+b-1524.5,i=((Math.floor((jd+50)%60)%60)+60)%60;return {stem:gan[i%10],pillar:gan[i%10]+zhi[i%12],element:wx[i%10]};}
$('#birth-form').onsubmit=e=>{e.preventDefault();const dateParts=$('#birthday').value.split('-').map(Number),result=getDay(...dateParts);profileDraft={stem:result.stem};for(const[k]of quickFields)profileDraft[k]=String(e.target.elements['quick-'+k].value||'').trim();if(!profileDraft.age){let age=now.getFullYear()-dateParts[0];if(now.getMonth()+1<dateParts[1]||(now.getMonth()+1===dateParts[1]&&now.getDate()<dateParts[2]))age--;profileDraft.age=String(age);}showResult(result);enhanceResult();};
function enhanceResult(){
 const panel=document.querySelectorAll('.step-panel')[1],summary=document.createElement('div');summary.className='quick-summary';
 for(const[k,t]of quickFields){const item=document.createElement('div'),label=document.createElement('span'),value=document.createElement('b');label.textContent=t;value.textContent=profileDraft[k]||'待补充';item.append(label,value);summary.append(item);}panel.querySelector('.actions').before(summary);
 const count=quickFields.filter(([k])=>profileDraft[k]).length,note=document.createElement('p');note.className='small-note';note.textContent=`已填写 ${count}/9 项亮点。下一步确认公开范围，未公开的收入或资产不会放进分享卡。`;summary.after(note);
 const a=panel.querySelector('a[href="friends.html#me"]');a.textContent=count===9?'确认公开范围，预览我的交友卡 ↗':'继续补齐亮点，生成交友卡 ↗';a.onclick=e=>{e.preventDefault();try{sessionStorage.setItem('runae-profile-draft',JSON.stringify(profileDraft));location.href='friends.html#me';}catch{note.textContent='当前浏览器不支持跨页暂存，可留在本页查看资料；进入交友页后需重新核对填写。';a.onclick=null;a.textContent='进入交友页核对资料';a.href='friends.html#me';}};
}
function showResult(r){const cycle=['木','火','土','金','水'],idx=cycle.indexOf(r.element),birthMe=cycle[(idx+4)%5],same=r.element,meBirth=cycle[(idx+1)%5];const stemsOf=el=>gan.filter((g,i)=>wx[i]===el).join('、');$('#main').innerHTML=`<section class="result"><button class="back" id="again">← 重新输入</button><span class="tiny-cap">YOUR DAY MASTER</span><div class="result-glyph">${r.stem}</div><h2>你是${r.stem}${r.element}日主。</h2><p class="subline">日柱 ${r.pillar} · 公历日期简算<br>原始出生日期未保存，也不会放进交友卡。</p><section class="step-panel"><div class="step-heading"><span>01</span><h3>可以进一步了解的找人方向</h3></div><div class="direction"><b>${stemsOf(birthMe)} · ${birthMe}日主</b><span>${birthMe}生${r.element} · 生我</span></div><div class="direction"><b>${stemsOf(same)} · ${same}日主</b><span>同五行</span></div><div class="direction"><b>${stemsOf(meBirth)} · ${meBirth}日主</b><span>${r.element}生${meBirth} · 我生</span></div><p class="small-note">以上只是日主层面的传统关系方向，没有优劣排名。正式推荐谁，需要结合完整八字与双方现实期待；当前未接入完整分析。</p></section><section class="step-panel"><div class="step-heading"><span>02</span><h3>把你的亮点，做成一张交友卡</h3></div><p>补充九项个人条件，确认想认识的生肖、日主，选择自己的爱好。哪些内容公开，由你决定。</p><div class="actions"><a class="primary" href="friends.html#me">完善资料，预览我的卡 ↗</a><a class="secondary" href="posters.html">先看看四种海报样式</a></div><p class="small-note">当前为页面设计预览：本次日主不会自动传入另一个静态页面；建档时需核对填写。</p></section><section class="step-panel"><div class="step-heading"><span>03</span><h3>有人想认识你，也有人还在路上</h3></div><p>你可以选择加入匹配，或先把海报分享出去。别人扫描线上邀请二维码后，查自己的日主、生成自己的卡，也可以申请认识你。</p><div class="future-code">专属二维码：线上邀请服务接通后生成<br>本地预览不生成无效二维码，不收集他人资料。</div><label class="consent"><input id="join" type="checkbox">我愿意将资料用于交友推荐（本地体验，不实际提交）</label><button class="secondary" id="preview-pool">看看推荐页面的样子</button><p class="notice">当前没有真实用户库；匹配页面中的人物均为虚构示例，不展示伪造的“已有合适用户”通知。</p></section></section>`;$('#again').onclick=()=>location.reload();$('#preview-pool').onclick=()=>{if(!$('#join').checked){$('#join').reportValidity();$('#join').required=true;$('#join').reportValidity();return;}location.href='friends.html';};window.scrollTo({top:0,behavior:'instant'});}
